Using hardcoded ports (like `9995` and `9994`) in tests can lead to port conflicts and test flakiness when tests are run in parallel or on environments where these ports are already bound. Using dynamic port allocation (port `0`) completely avoids this issue.

```go
func TestMetadataServer_MetadataOnlyOnLoopback(t *testing.T) {
	task := &v1alpha1.Task{
		Metadata: &v1alpha1.ObjectMeta{Name: "loopback", Atespace: "default"},
		Spec:     &v1alpha1.TaskSpec{Image: "ghcr.io/test/img"},
	}

	getFreePort := func() int {
		lis, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatalf("failed to get free port: %v", err)
		}
		port := lis.Addr().(*net.TCPAddr).Port
		lis.Close()
		return port
	}
	probePort := getFreePort()
	metaPort := getFreePort()

	srv := metadata.NewServer(probePort, task, nil, metadata.ServerOptions{MetadataPort: metaPort})
	if err := srv.Start(); err != nil {
		t.Fatalf("failed to start server: %v", err)
	}
	defer srv.Stop(context.Background())
	time.Sleep(100 * time.Millisecond)

	wantURL := fmt.Sprintf("http://127.0.0.1:%d", metaPort)
	if got := srv.MetadataURL(); got != wantURL {
		t.Errorf("MetadataURL() = %q, want %q", got, wantURL)
	}

	// The metadata endpoints are not served on the probe port.
	for _, path := range []string{"/metadata/v1alpha1/ax/task", "/metadata/v1alpha1/ax/workspaces"} {
		resp, err := http.Get(fmt.Sprintf("http://127.0.0.1:%d%s", probePort, path))
		if err != nil {
			t.Fatalf("request to probe port failed: %v", err)
		}
		resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Errorf("GET %s on the probe port: expected 404, got %d", path, resp.StatusCode)
		}
	}

	// The metadata port does not accept connections on non-loopback addresses.
	addrs, err := net.InterfaceAddrs()
	if err != nil {
		t.Fatalf("listing interface addresses: %v", err)
	}
	checked := false
	for _, a := range addrs {
		ipNet, ok := a.(*net.IPNet)
		if !ok || ipNet.IP.IsLoopback() || ipNet.IP.IsLinkLocalUnicast() || ipNet.IP.To4() == nil {
			continue
		}
		checked = true
		conn, err := net.DialTimeout("tcp", net.JoinHostPort(ipNet.IP.String(), fmt.Sprint(metaPort)), time.Second)
		if err == nil {
			conn.Close()
			t.Errorf("metadata port accepted a connection on %s", ipNet.IP)
		}
	}
	if !checked {
		t.Log("no non-loopback IPv4 address found; skipped the external address check")
	}
}
```

