Update the `renew` method to accept a `context.Context` instead of a `stop` channel. This allows the active `renewScript.Run` call to be cancelled immediately when `unlock()` is called, preventing `unlock()` from blocking on a slow or hung Redis connection.

```go
func (r *RedisLocker) renew(ctx context.Context, key, token string) {
	interval := r.ttl / 3
	if interval <= 0 {
		interval = time.Millisecond
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	ttlMillis := r.ttl.Milliseconds()
	if ttlMillis <= 0 {
		ttlMillis = 1
	}

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}

		renewCtx, cancel := context.WithTimeout(ctx, interval)
		res, err := renewScript.Run(renewCtx, r.client, []string{key}, token, ttlMillis).Int()
		cancel()
		if err != nil {
			if errors.Is(err, context.Canceled) {
				return
			}
			// Transient Redis error: keep trying on the next tick while the
			// remaining TTL still covers us.
			slog.Warn("renewing lock lease", "key", key, "error", err)
			continue
		}
		if res == 0 {
			// The lock expired or was taken over; there is nothing left to renew.
			slog.Error("lock lease lost before release", "key", key)
			return
		}
	}
}
```

